function buildHomeLlmRuntimeStatus(
  selectedProjectId: string,
  configSummary: StudioConfigSummary | null,
  safeApiCacheStatuses: SafeApiCacheStatus[],
  modelAssignmentChecked: boolean
): HomeLlmRuntimeStatus {
  const providerType = (configSummary?.llm_provider ?? "unknown").trim().toLowerCase();
  const providerStatus = (configSummary?.provider_status ?? "").trim().toLowerCase();
  const providerModelCache = readSafeApiCache<ReturnType<typeof buildProviderModelListSafeCacheSummary>>(providerModelListCacheKey(selectedProjectId));
  const safeProviderTypes = providerModelCache?.value.provider_types.map((type) => type.trim().toLowerCase()).filter(Boolean) ?? [];
  const providerTypeSet = safeProviderTypes.length ? safeProviderTypes : [providerType];
  const hasRealProviderType = providerTypeSet.some((type) => type !== "mock" && type !== "local_stub" && type !== "unknown");
  const mockOrStub = providerTypeSet.every((type) => type === "mock" || type === "local_stub");
  const providerConfigured = Boolean(
    configSummary?.api_key_configured ||
    providerStatus === "configured" ||
    providerStatus === "ready" ||
    mockOrStub ||
    providerType === "local_http" ||
    (providerModelCache?.value.provider_count ?? 0) > 0
  );
  const providerCacheText = safeApiCacheStatuses
    .filter((status) => status.scope === "provider")
    .map((status) => `${status.key} ${status.label} ${status.summary} ${status.safeError ?? ""}`)
    .join(" ")
    .toLowerCase();
  const hasConnectedCache = /\bconnected\b|连接成功/.test(providerCacheText);
  const hasMissingSecretCache = /missing_secret|missing secret|缺少 api key|缺少密钥/.test(providerCacheText);
  const hasAuthFailedCache = /auth_failed|认证失败|authentication/.test(providerCacheText);
  const hasFailedCache = /failed|失败|timeout|超时/.test(providerCacheText);
  const providerConnection = mockOrStub
    ? "使用 mock/local_stub"
    : !providerConfigured
      ? "provider 未连接"
      : hasConnectedCache
        ? "provider connected / 连接成功"
        : hasMissingSecretCache
          ? "缺少 API key（安全提示）"
          : hasAuthFailedCache
            ? "认证失败（已脱敏）"
            : hasFailedCache
              ? "连接失败（已脱敏）"
              : "已配置，等待手动 Test Connection";
  const usesRealLlm = mockOrStub && !hasRealProviderType
    ? "否，当前使用 mock/local_stub"
    : providerConfigured || hasRealProviderType
      ? "是，已配置真实/本地 LLM；仅手动触发连接"
      : "未启用，等待配置模型服务";
  const modelAssignment = modelAssignmentChecked ? "模型已配置" : "模型缺失";
  const modeReadinessText = mockOrStub
    ? "使用 mock/local_stub"
    : !modelAssignmentChecked
      ? "模型缺失"
      : hasConnectedCache
        ? "模型已配置"
        : "provider 未连接";

  return {
    statusKind: (providerConfigured || hasRealProviderType) && (mockOrStub || modelAssignmentChecked) ? "ready" : providerConfigured ? "warning" : "missing",
    usesRealLlm,
    providerConnection,
    modelAssignment,
    detail: "首页只读取安全配置摘要和 Provider 状态缓存；不会自动调用真实 provider，不显示 API key、Authorization header 或 raw provider error。",
    modeReadiness: {
      novel: modeReadinessText,
      tavern: modeReadinessText,
      world: modeReadinessText
    }
  };
}

type HomeNextStepKind =
  | "missing_project"
  | "missing_provider"
  | "provider_not_tested"
  | "missing_model_list"
  | "missing_model_assignment"
  | "missing_novel_manuscript"
  | "missing_tavern_character"
  | "missing_world_save"
  | "ready";

type HomeNextStep = {
  kind: HomeNextStepKind;
  title: string;
  detail: string;
  actionLabel: string;
  targetMode: AppMode;
};

type MainModeFlow = {
  status: string;
  next: string;
  recent: string;
  provider: string;
  primary: string;
  secondary: string;
};

type MainModeCardProps = {
  testId: string;
  eyebrow: string;
  title: string;
  readiness: string;
  flow: MainModeFlow;
  primaryTestId: string;
  secondaryTestId: string;
  onPrimary: () => void;
  onSecondary: () => void;
};

function buildHomeProviderNextStepSignals(
  selectedProjectId: string,
  safeApiCacheStatuses: SafeApiCacheStatus[],
  llmRuntimeStatus: HomeLlmRuntimeStatus,
  modelAssignmentChecked: boolean
) {
  const providerModelCache = readSafeApiCache<ReturnType<typeof buildProviderModelListSafeCacheSummary>>(providerModelListCacheKey(selectedProjectId));
  const providerCacheText = safeApiCacheStatuses
    .filter((status) => status.scope === "provider")
    .map((status) => `${status.key} ${status.label} ${status.summary} ${status.safeError ?? ""}`)
    .join(" ")
    .toLowerCase();
  const mockOrStub = /mock|local_stub/.test(`${llmRuntimeStatus.usesRealLlm} ${llmRuntimeStatus.providerConnection}`.toLowerCase());
  const hasProviderTested = Boolean(
    mockOrStub ||
    /connected|连接成功|auth_failed|认证失败|missing_secret|缺少 api key|缺少密钥|timeout|超时|failed|失败|tested|test connection/.test(providerCacheText)
  );
  const hasModelList = Boolean(
    mockOrStub ||
    (providerModelCache?.value.model_count ?? 0) > 0 ||
    safeApiCacheStatuses.some((status) => status.scope === "provider" && status.key.includes("provider-model-list") && !status.failed && (status.itemCount ?? 0) > 0)
  );
  const hasModelAssignment = Boolean(
    modelAssignmentChecked &&
    (safeApiCacheStatuses.some((status) => status.key.includes("model-assignment")) || mockOrStub || hasModelList)
  );

  return { hasProviderTested, hasModelList, hasModelAssignment };
}

function buildHomeNextStep({
  hasProject,
  providerConfigured,
  hasProviderTested,
  hasModelList,
  hasModelAssignment,
  recentSaveCount
}: {
  hasProject: boolean;
  providerConfigured: boolean;
  hasProviderTested: boolean;
  hasModelList: boolean;
  hasModelAssignment: boolean;
  recentSaveCount: number;
}): HomeNextStep {
  if (!hasProject) {
    return {
      kind: "missing_project",
      title: "打开/创建项目",
      detail: "先打开或创建本地项目，也可以一键体验 Demo 项目。不会上传路径或读取敏感完整路径。",
      actionLabel: "打开/创建项目",
      targetMode: "project"
    };
  }
  if (!providerConfigured) {
    return {
      kind: "missing_provider",
      title: "配置模型服务",
      detail: "选择 OpenAI、OpenAI-compatible、中转站、本地模型服务或 mock/local_stub。API Key 不会显示或保存到项目。",
      actionLabel: "配置模型服务",
      targetMode: "prompt_lab"
    };
  }
  if (!hasProviderTested) {
    return {
      kind: "provider_not_tested",
      title: "测试连接",
      detail: "模型服务已配置，下一步由用户手动点击 Test Connection；首页不会自动调用真实 provider。",
      actionLabel: "测试连接",
      targetMode: "prompt_lab"
    };
  }
  if (!hasModelList) {
    return {
      kind: "missing_model_list",
      title: "读取模型或手动添加模型",
      detail: "连接测试后读取模型列表；如果 provider 不支持列表，也可以手动添加 model_id。",
      actionLabel: "读取模型或手动添加模型",
      targetMode: "prompt_lab"
    };
  }
  if (!hasModelAssignment) {
    return {
      kind: "missing_model_assignment",
      title: "按模式分配模型",
      detail: "为写小说、角色 RP、世界输入解析、世界叙事、Cross-Mode 和质量检查分配模型。",
      actionLabel: "按模式分配模型",
      targetMode: "prompt_lab"
    };
  }
  if (recentSaveCount <= 0) {
    return {
      kind: "missing_world_save",
      title: "开始大世界",
      detail: "模型和项目已准备好；没有存档时可以先开始大世界，也可以创建稿件或角色。",
      actionLabel: "开始大世界",
      targetMode: "play"
    };
  }
  return {
    kind: "ready",
    title: "继续写作 / RP / 游玩",
    detail: "本地项目、模型服务和模型分配已具备安全摘要；可以继续写小说、角色 RP 或大世界游玩。",
    actionLabel: "继续写作 / RP / 游玩",
    targetMode: "project"
  };
}

